const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Check products table schema
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name='products'\").get();
console.log('PRODUCTS SCHEMA:', schema.sql);
console.log();

// Find the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('PRODUCT:', JSON.stringify(product, null, 2));
"

node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Look up the compatible products
const compatIds = ['PROD-B98D14','PROD-FA0948','PROD-2DBA15','PROD-7C0240'];
const placeholders = compatIds.map(() => '?').join(',');
const compatProducts = db.prepare('SELECT product_id, name FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
console.log('Compatible products:');
compatProducts.forEach(p => console.log(' ', p.product_id, '-', p.name));

console.log();

// Also search for 'Wireless Mouse' product
const mouseProducts = db.prepare(\"SELECT product_id, name FROM products WHERE name LIKE '%Wireless Mouse%'\").all();
console.log('Products matching Wireless Mouse:');
mouseProducts.forEach(p => console.log(' ', p.product_id, '-', p.name));
"

